INSERT INTO faq (pertanyaan, jawaban, urutan) VALUES
('Apa itu Ruang Hukum?', 'Ruang Hukum adalah layanan konsultasi hukum online. Anda menuliskan pertanyaan, lalu pengacara terverifikasi di bidang yang Anda pilih menjawabnya secara privat satu lawan satu.', 1),
('Apakah konsultasi di Ruang Hukum dikenakan biaya?', 'Di versi ini belum ada fitur pembayaran, sehingga seluruh konsultasi berjalan tanpa tagihan.', 2),
('Bagaimana cara mengajukan konsultasi?', 'Daftar atau masuk sebagai klien, buka Dashboard, lalu klik Ajukan Konsultasi. Pilih bidang hukum, tulis judul dan pertanyaan Anda, kemudian kirim. Konsultasi akan muncul di riwayat dengan status Menunggu.', 3),
('Bidang hukum apa saja yang tersedia?', 'Saat ini tersedia enam bidang: Hukum Pidana, Hukum Perdata, Hukum Keluarga, Hukum Ketenagakerjaan, Hukum Bisnis, dan Hukum Properti.', 4),
('Siapa yang akan menjawab pertanyaan saya?', 'Pertanyaan Anda dapat dijawab oleh pengacara yang sudah diverifikasi admin dan memiliki bidang keahlian yang sama dengan bidang yang Anda pilih.', 5),
('Apa arti status Menunggu, Dijawab, Selesai, dan Ditutup?', 'Menunggu berarti pertanyaan belum dijawab. Dijawab berarti pengacara sudah membalas. Selesai berarti Anda menandai konsultasi sudah tuntas. Ditutup berarti konsultasi tidak menerima balasan lagi.', 6),
('Bisakah saya membalas setelah pengacara menjawab?', 'Bisa. Setelah pengacara menjawab, Anda dapat melanjutkan percakapan di halaman detail konsultasi atau menandainya selesai jika pertanyaan Anda sudah terjawab.', 7),
('Apakah isi konsultasi saya bersifat privat?', 'Konsultasi berlangsung satu lawan satu antara klien dan pengacara yang menanganinya, tidak ditampilkan di forum atau halaman publik.', 8),
('Bagaimana cara memilih pengacara?', 'Buka menu Pengacara untuk mencari berdasarkan nama atau kata kunci, lalu saring menurut bidang dan kota. Setiap kartu menampilkan bidang keahlian dan lama pengalaman pengacara.', 9),
('Bagaimana cara mendaftar sebagai pengacara?', 'Pada halaman Daftar pilih peran Pengacara, lalu isi bidang keahlian dan nomor izin advokat. Akun baru aktif setelah admin memverifikasinya, dan sebelum itu Anda belum bisa masuk.', 10),
('Apakah jawaban pengacara sama dengan nasihat hukum resmi untuk perkara saya?', 'Jawaban di Ruang Hukum bersifat informasi awal berdasarkan keterangan yang Anda tulis. Untuk perkara yang rumit atau mendesak, sebaiknya Anda bertemu langsung dengan pengacara.', 11),
('Saya lupa kata sandi. Apa yang harus dilakukan?', 'Fitur pengaturan ulang kata sandi belum tersedia. Silakan hubungi admin Ruang Hukum untuk bantuan.', 12);
INSERT INTO artikel (penulis_id, bidang_id, judul, slug, ringkasan, isi, status, created_at) VALUES
((SELECT id FROM users WHERE email = 'admin@ruanghukum.test' LIMIT 1), (SELECT id FROM bidang_hukum WHERE nama = 'Hukum Pidana'), 'Hak Anda Saat Diperiksa oleh Polisi', 'hak-anda-saat-diperiksa-polisi', 'Mengetahui hak dasar saat diperiksa membantu Anda tetap tenang dan tidak merugikan diri sendiri.', 'Pemeriksaan oleh polisi dapat membuat siapa pun gugup. Mengetahui hak dasar membantu Anda tetap tenang.\n\nPertama, Anda berhak mengetahui alasan Anda dipanggil atau diperiksa, termasuk apakah Anda berstatus saksi atau tersangka. Kedua, Anda berhak didampingi penasihat hukum selama pemeriksaan. Ketiga, Anda berhak memberi keterangan secara bebas tanpa tekanan atau paksaan.\n\nSebelum menandatangani berita acara pemeriksaan, baca seluruh isinya dengan teliti. Jika ada keterangan yang tidak sesuai, minta diperbaiki sebelum Anda menandatangani. Simpan salinan surat panggilan dan catat waktu serta nama petugas yang memeriksa.\n\nTulisan ini informasi umum dan bukan pengganti nasihat hukum untuk kasus Anda. Untuk situasi tertentu, ajukan konsultasi kepada pengacara di bidang hukum pidana.', 'terbit', '2026-11-06 09:00:00'),
((SELECT id FROM users WHERE email = 'admin@ruanghukum.test' LIMIT 1), (SELECT id FROM bidang_hukum WHERE nama = 'Hukum Perdata'), 'Mengenal Somasi: Peringatan Sebelum Gugatan', 'mengenal-somasi-peringatan-sebelum-gugatan', 'Somasi adalah surat teguran resmi yang sering menjadi langkah awal sebelum perkara dibawa ke pengadilan.', 'Somasi adalah surat teguran resmi yang meminta pihak lain memenuhi kewajibannya, misalnya membayar utang atau menyerahkan barang sesuai perjanjian.\n\nSomasi umumnya memuat identitas para pihak, uraian perjanjian atau kejadian, kewajiban yang belum dipenuhi, batas waktu pemenuhan yang wajar, serta akibat jika kewajiban tetap diabaikan. Kirim melalui cara yang bisa dibuktikan, misalnya surat tercatat, dan simpan tanda terimanya.\n\nSomasi sering menjadi langkah awal sebelum perkara dibawa ke pengadilan karena menunjukkan bahwa Anda sudah memberi kesempatan kepada pihak lain untuk menyelesaikan masalah. Isi dan bentuknya bergantung pada kasus, sehingga sebaiknya dikonsultasikan lebih dulu. Tulisan ini informasi umum dan bukan pengganti nasihat hukum untuk kasus Anda.', 'terbit', '2026-11-05 10:00:00'),
((SELECT id FROM users WHERE email = 'admin@ruanghukum.test' LIMIT 1), (SELECT id FROM bidang_hukum WHERE nama = 'Hukum Keluarga'), 'Hak Asuh Anak dan Harta Bersama Saat Bercerai', 'hak-asuh-anak-dan-harta-bersama-saat-bercerai', 'Dua pertanyaan besar saat bercerai: siapa yang mengasuh anak dan bagaimana harta dibagi.', 'Perceraian membawa dua pertanyaan besar: siapa yang mengasuh anak dan bagaimana harta dibagi.\n\nDalam urusan anak, pertimbangan utama adalah kepentingan terbaik anak, seperti kebutuhan kasih sayang, pendidikan, dan kestabilan lingkungan. Orang tua yang tidak memegang hak asuh tetap berkewajiban turut membiayai anak.\n\nHarta bersama pada umumnya adalah harta yang diperoleh selama perkawinan, sedangkan harta bawaan serta harta yang diperoleh sebagai warisan atau hibah biasanya tetap menjadi milik masing-masing. Perjanjian pranikah, bila ada, dapat mengatur hal ini secara berbeda.\n\nKetentuan rinci dapat berbeda bagi yang beragama Islam dan non-Islam, termasuk pengadilan yang menanganinya. Karena itu, konsultasikan situasi Anda secara pribadi. Tulisan ini informasi umum dan bukan pengganti nasihat hukum untuk kasus Anda.', 'terbit', '2026-11-04 09:30:00'),
((SELECT id FROM users WHERE email = 'admin@ruanghukum.test' LIMIT 1), (SELECT id FROM bidang_hukum WHERE nama = 'Hukum Ketenagakerjaan'), 'PKWT dan PKWTT: Apa Bedanya?', 'pkwt-dan-pkwtt-apa-bedanya', 'Memahami perbedaan kontrak kerja waktu tertentu dan waktu tidak tertentu sebelum menandatangani.', 'Dua istilah ini sering muncul di kontrak kerja. PKWT adalah perjanjian kerja waktu tertentu, artinya hubungan kerja berlaku untuk jangka waktu atau pekerjaan tertentu. PKWTT adalah perjanjian kerja waktu tidak tertentu, yang sering disebut karyawan tetap.\n\nPerbedaan pentingnya ada pada masa berlaku, batas perpanjangan, dan hak ketika hubungan kerja berakhir. PKWT berakhir sesuai jangka waktunya, sedangkan PKWTT berakhir karena alasan dan prosedur tertentu, misalnya pengunduran diri atau pemutusan hubungan kerja.\n\nBaca kontrak Anda dengan teliti: periksa jangka waktu, jabatan, upah, dan ketentuan berakhirnya hubungan kerja. Jika ragu, minta salinannya dan konsultasikan sebelum menandatangani. Aturan dapat berubah, jadi pastikan Anda memeriksa ketentuan yang berlaku. Tulisan ini informasi umum dan bukan pengganti nasihat hukum untuk kasus Anda.', 'terbit', '2026-11-03 08:30:00'),
((SELECT id FROM users WHERE email = 'admin@ruanghukum.test' LIMIT 1), (SELECT id FROM bidang_hukum WHERE nama = 'Hukum Bisnis'), 'Mendaftarkan Merek Usaha Anda', 'mendaftarkan-merek-usaha-anda', 'Perlindungan merek pada dasarnya diperoleh melalui pendaftaran, bukan hanya karena sudah dipakai.', 'Merek adalah identitas usaha: nama, logo, atau kombinasi keduanya yang membedakan produk Anda dari milik orang lain.\n\nPerlindungan merek di Indonesia pada dasarnya diperoleh melalui pendaftaran di Direktorat Jenderal Kekayaan Intelektual (DJKI). Artinya, merek yang sudah dipakai lama belum tentu terlindungi jika belum didaftarkan.\n\nLangkah umumnya: telusuri dulu apakah sudah ada merek yang mirip, siapkan data pemohon dan contoh merek, tentukan kelas barang atau jasa, lalu ajukan permohonan dan ikuti pemeriksaannya. Biaya dan lama prosesnya dapat berubah, jadi periksa informasi terbaru di situs resmi DJKI. Tulisan ini informasi umum dan bukan pengganti nasihat hukum untuk kasus Anda.', 'terbit', '2026-11-02 11:00:00'),
((SELECT id FROM users WHERE email = 'admin@ruanghukum.test' LIMIT 1), (SELECT id FROM bidang_hukum WHERE nama = 'Hukum Properti'), 'Hal yang Perlu Dicek Sebelum Membeli Tanah', 'hal-yang-perlu-dicek-sebelum-membeli-tanah', 'Banyak sengketa tanah bermula dari pemeriksaan awal yang kurang teliti sebelum transaksi.', 'Membeli tanah adalah keputusan besar, dan banyak sengketa muncul karena pemeriksaan awal yang kurang teliti.\n\nPeriksa dulu bukti kepemilikannya, misalnya sertifikat, dan cocokkan nama pemilik dengan identitasnya. Minta pengecekan sertifikat di kantor pertanahan untuk memastikan tanah tidak sedang bersengketa, diagunkan, atau diblokir. Lihat juga batas dan luas tanah di lapangan, serta peruntukan lahannya menurut tata ruang.\n\nJual beli sebaiknya dibuat di hadapan Pejabat Pembuat Akta Tanah (PPAT), lalu dilanjutkan dengan balik nama sertifikat. Jangan hanya mengandalkan kuitansi tanpa akta. Tulisan ini informasi umum dan bukan pengganti nasihat hukum untuk kasus Anda. Untuk transaksi nyata, konsultasikan dengan pengacara di bidang properti.', 'terbit', '2026-11-01 14:00:00');
